-- FLOAT·DOUBLE 기본값: MySQL 이 이진 값을 다시 찍은 표기와 같게 저장하는 꼴 (지수 표기·반올림이 생기는 꼴은 RE_EXPORT 로 거부한다 — float-default.test.ts)
ALTER TABLE member
  ADD COLUMN f1 FLOAT DEFAULT 0, ADD COLUMN f2 FLOAT DEFAULT 1.5, ADD COLUMN f3 FLOAT DEFAULT '1.50', ADD COLUMN f4 FLOAT DEFAULT 123456,
  ADD COLUMN f5 FLOAT DEFAULT 0.000001, ADD COLUMN f6 FLOAT DEFAULT -2.5, ADD COLUMN f7 FLOAT DEFAULT 100000000000, ADD COLUMN f8 FLOAT UNSIGNED DEFAULT '1e2',
  ADD COLUMN g1 DOUBLE DEFAULT 3.14159265, ADD COLUMN g2 DOUBLE DEFAULT 1234567, ADD COLUMN g3 DOUBLE DEFAULT '1e14', ADD COLUMN g4 DOUBLE DEFAULT 999999999999999,
  ADD COLUMN g5 DOUBLE DEFAULT '1e-15', ADD COLUMN g6 DOUBLE DEFAULT -0.000000000000123456789, ADD COLUMN g7 DOUBLE NOT NULL DEFAULT '0.5', ADD COLUMN g8 REAL DEFAULT 1.25,
  ADD COLUMN p1 FLOAT(7,3) DEFAULT 1.5, ADD COLUMN p2 FLOAT(7,3) DEFAULT 0, ADD COLUMN p3 FLOAT(10,2) DEFAULT 10000, ADD COLUMN p4 FLOAT(10,2) DEFAULT 123456.78,
  ADD COLUMN q1 DOUBLE(10,2) NOT NULL DEFAULT 0, ADD COLUMN q2 DOUBLE(10,2) NOT NULL DEFAULT '0.00', ADD COLUMN q3 DOUBLE(10,2) DEFAULT 1234567,
  ADD COLUMN q4 DOUBLE(10,2) DEFAULT -99999999.99, ADD COLUMN q5 DOUBLE(10,0) DEFAULT 12, ADD COLUMN q6 DOUBLE(20,10) DEFAULT 0.1, ADD COLUMN q7 DOUBLE(10,2) UNSIGNED DEFAULT '1e2';
ALTER TABLE member ALTER COLUMN q3 SET DEFAULT 5, ALTER COLUMN p1 SET DEFAULT -1.5, ALTER COLUMN g1 SET DEFAULT 0.1;
ALTER TABLE orders MODIFY amount DOUBLE(12,4) NOT NULL DEFAULT 2.5;
